writing.exampleCode:
fn scalar_count(text: impl AsRef<str>) -> usize {
    text.as_ref().trim().chars().count()
}
fn main() {
    let owned = String::from(" É🦀 ");
    assert_eq!(scalar_count(&owned), 2);
    assert_eq!(owned, " É🦀 ");
}

